using System;
using System.Drawing;
using System.Windows.Forms;
internal partial class Player {
    Motion dockMorph,dockSettle;Point dockStart,dockEnd,dockPrevious;PointF dockVelocity;DateTime dockMoved;bool dockSettling;Surface floatingNavigation;bool draggingNavigation;Point navigationGrab;DateTime navigationHiddenUntil;
    sealed class NavigationScrollFilter:IMessageFilter {internal Player Owner;public bool PreFilterMessage(ref Message message){if(message.Msg==0x20a&&Owner!=null&&!Owner.closing&&Form.FromChildHandle(message.HWnd)==Owner)Owner.navigationHiddenUntil=DateTime.UtcNow.AddMilliseconds(850);return false;}}
    void BuildFloatingNavigation(){
        floatingNavigation=new Surface{BackColor=Theme.Ink,AccessibleName="Draggable navigation dock"};Controls.Add(floatingNavigation);dockMorph=new Motion(()=>floatingNavigation.Invalidate());dockSettle=new Motion(delegate{floatingNavigation.Location=new Point((int)(dockStart.X+(dockEnd.X-dockStart.X)*dockSettle.Value),(int)(dockStart.Y+(dockEnd.Y-dockStart.Y)*dockSettle.Value));},delegate{dockSettling=false;featuresState.DockX=dockEnd.X;featuresState.DockY=dockEnd.Y;SaveFeatures();});floatingNavigation.PaintSurface=delegate(Graphics g,Rectangle r){PaintGlass(g,new Rectangle(1,1,r.Width-3,r.Height-3),(int)(30-14*dockMorph.Value),ArtworkTone(Cover(Current)));using(var pen=new Pen(Theme.Muted,2))g.DrawLine(pen,r.Width/2-15,9,r.Width/2+15,9);};
        string[] names={"Home","Search","Library","Queue"},icons={"\uE80F","\uE721","\uE8F1","\uE8FD"};for(int i=0;i<4;i++){int k=i;var button=Make(floatingNavigation,names[i],delegate{ShowPage(names[k]);},delegate(Graphics g,Rectangle r){Glyph(g,icons[k],new Rectangle(0,1,r.Width,23),page==names[k]?Theme.Peach:Theme.Paper,15);TextAt(g,names[k],new Rectangle(0,25,r.Width,20),8,Theme.Paper,false,true);});button.SetBounds(10+i*66,18,64,46);}
