        floatingNavigation.MouseMove+=delegate(object sender,MouseEventArgs e){if(!draggingNavigation)return;var p=PointToClient(floatingNavigation.PointToScreen(e.Location));featuresState.DockX=p.X-navigationGrab.X;featuresState.DockY=p.Y-navigationGrab.Y;LayoutFloatingNavigation();double elapsed=Math.Max(.01,(DateTime.UtcNow-dockMoved).TotalSeconds);dockVelocity=new PointF((float)Math.Max(-600,Math.Min(600,(floatingNavigation.Left-dockPrevious.X)/elapsed)),(float)Math.Max(-600,Math.Min(600,(floatingNavigation.Top-dockPrevious.Y)/elapsed)));dockPrevious=floatingNavigation.Location;dockMoved=DateTime.UtcNow;};
        floatingNavigation.MouseUp+=delegate{if(!draggingNavigation)return;draggingNavigation=false;floatingNavigation.Capture=false;dockMorph.To(0,240);dockStart=floatingNavigation.Location;dockEnd=new Point(Math.Max(8,Math.Min(dockStart.X+(int)(dockVelocity.X*.12),ClientSize.Width-floatingNavigation.Width-8)),Math.Max(8,Math.Min(dockStart.Y+(int)(dockVelocity.Y*.12),ClientSize.Height-90)));dockSettling=true;dockSettle.To(1,260,true);};
