    }
    void LayoutFloatingNavigation(){if(floatingNavigation==null)return;bool visible=featuresState.FloatingNavigation&&(draggingNavigation||DateTime.UtcNow>=navigationHiddenUntil);floatingNavigation.Visible=visible;if(!visible||dockSettling)return;int width=Math.Min(284,ClientSize.Width-16);int x=Math.Max(8,Math.Min(featuresState.DockX,ClientSize.Width-width-8)),y=Math.Max(8,Math.Min(featuresState.DockY,ClientSize.Height-78));floatingNavigation.SetBounds(x,y,width,70);floatingNavigation.BringToFront();}
}
